const content = $input.first().json.choices?.[0]?.message?.content;

if (typeof content !== 'string' || !content.trim()) {
  throw new Error('OpenAI response has no message content');
}

let extracted;

try {
  extracted = JSON.parse(content);
} catch {
  throw new Error('OpenAI response is not valid JSON');
}

if (
  !extracted ||
  !Array.isArray(extracted.attendees) ||
  !Array.isArray(extracted.actions) ||
  typeof extracted.summary !== 'string'
) {
  throw new Error('OpenAI response does not match the expected schema');
}

const settings = $('Settings').first().json;
const clean = value => typeof value === 'string' ? value.trim() : '';

const attendees = extracted.attendees.map(clean).filter(Boolean);

function getPriorityInfo(due) {
  const d = (due || '').trim();

  if (!d || d === '미정' || d.includes('미정')) {
    return { priority: 4, priority_label: '4순위' };
  }

  if (d.includes('오늘') || d.includes('금일') || d.includes('당일')) {
    return { priority: 1, priority_label: '1순위' };
  }

  if (
    d.includes('다음 주') ||
    d.includes('다음주') ||
    d.includes('차주') ||
    d.includes('내주')
  ) {
    return { priority: 3, priority_label: '3순위' };
  }

  if (
    d.includes('이번 주') ||
    d.includes('이번주') ||
    d.includes('금주') ||
    /(월|화|수|목|금|토|일)요일/.test(d) ||
    /(월|화|수|목|금|토|일)까지/.test(d)
  ) {
    return { priority: 2, priority_label: '2순위' };
  }

  return { priority: 4, priority_label: '4순위' };
}

const actions = extracted.actions
  .map(item => {
    const task = clean(item.task);
    const owner = clean(item.owner) || '미정';
    const due = clean(item.due) || '미정';
    const info = getPriorityInfo(due);

    return {
      priority: info.priority,
      priority_label: info.priority_label,
      task,
      owner,
      due
    };
  })
  .filter(item => item.task);

actions.sort((a, b) => a.priority - b.priority);

const title = clean(settings.title) || '제목 없음';
const summary = clean(extracted.summary);

const lines = [
  title,
  '',
  '참석자: ' + (attendees.join(', ') || '미정'),
  '요약: ' + (summary || '요약 없음'),
  '',
  '액션 아이템'
];

if (actions.length === 0) {
  lines.push('없음');
} else {
  actions.forEach(action => {
    lines.push(
      `${action.priority_label}: ${action.task} / ${action.owner} / ${action.due}`
    );
  });
}

return [{
  json: {
    title,
    route: 'meeting_notes',
    count: actions.length,
    attendees,
    summary,
    actions,
    report_text: lines.join('\n')
  }
}];
